import tempfile
import torch
import torch.nn as nn
from topologies import Trainer, build, synth
root = tempfile.mkdtemp()
@synth.generator
def sequences(ctx):
    features = torch.randn(6, generator=ctx.rng.torch)
    targets = features[:6].reshape(3, 2)
    return {"inputs": synth.Tensor(features), "targets": synth.Tensor(targets)}
dataset = synth.Spec("soft-dtw-sequences", generator=sequences, size=16, splits={"train": 1.0}, seed=11, root=root, monitor="none").run()
train = dataset.for_recipe("regression", split="train", input_field="inputs", target_field="targets", preserve_shape=True)
class SequenceRegressor(nn.Module):
    def __init__(self):
        super().__init__()
        self.network = build("mlp", "tiny", in_features=6, out_features=6)
    def forward(self, inputs):
        return self.network(inputs).reshape(-1, 3, 2)
model = SequenceRegressor()
trainer = Trainer(model, train, recipe="regression", recipe_config={"loss": "soft-dtw", "loss_kwargs": {"gamma": 1.0}}, batch_size=4, max_epochs=1, device="cpu")
trainer.fit()
